class Solution{
public:
    int lowerBound(vector<int> &nums, int x){
       int ans=nums.size();
       int low=0;
       int high=ans-1;

       while(low <= high){
    int mid = (low + high)/2;

    if(nums[mid] >= x)
        high = mid - 1;
    else
        low = mid + 1;
}
       return low;
    }
};
```

