class Solution {
    public int lowerBound(int[] nums, int x) {
      int n=nums.length;
      int start=0;
      int end=n-1;
      int ans=n;
      while(start<=end){
        int mid=start+(end-start)/2;
        if(nums[mid]>=x){
          ans=mid;
          end=mid-1;
        }
        else{
            start=mid+1;
        }
      }
      return ans;
     }
}
```

